```python
from datetime import datetime, timezone
from enum import Enum
from typing import Optional
from uuid import uuid4

from fastapi import FastAPI, HTTPException, Query
from pydantic import BaseModel

app = FastAPI(title="Todo API", version="2.0.0")


class Priority(str, Enum):
    low = "low"
    normal = "normal"
    high = "high"


class Todo(BaseModel):
    id: str
    title: str
    completed: bool = False
    created_at: str
    priority: Priority = Priority.normal


class TodoCreate(BaseModel):
    title: str
    priority: Priority = Priority.normal


class TodoReplace(BaseModel):
    title: str
    completed: bool
    priority: Priority = Priority.normal


class TodoPatch(BaseModel):
    title: Optional[str] = None
    completed: Optional[bool] = None
    priority: Optional[Priority] = None


LEGACY_TODO_ID = "legacy-todo"
STORE: dict[str, dict] = {
    LEGACY_TODO_ID: {
        "id": LEGACY_TODO_ID,
        "title": "legacy todo",
        "completed": False,
        "created_at": "2024-01-01T00:00:00+00:00",
    }
}


def _now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


@app.get("/todos")
def list_todos(limit: int = Query(20, ge=1, le=100), cursor: Optional[str] = None):
    items = sorted(STORE.values(), key=lambda t: t["id"])
    if cursor:
        items = [t for t in items if t["id"] > cursor]
    page = items[:limit]
    next_cursor = page[-1]["id"] if len(items) > limit else None
    return {
        "items": [{**todo, "priority": todo.get("priority", Priority.normal.value)} for todo in page],
        "next_cursor": next_cursor,
    }


@app.post("/todos", status_code=201, response_model=Todo)
def create_todo(body: TodoCreate):
    tid = str(uuid4())
    row = {
        "id": tid,
        "title": body.title,
        "completed": False,
        "created_at": _now(),
        "priority": body.priority.value,
    }
    STORE[tid] = row
    return row


@app.get("/todos/{todo_id}", response_model=Todo)
def get_todo(todo_id: str):
    row = STORE.get(todo_id)
    if not row:
        raise HTTPException(404, "todo not found")
    return row


@app.put("/todos/{todo_id}", response_model=Todo)
def replace_todo(todo_id: str, body: TodoReplace):
    if todo_id not in STORE:
        raise HTTPException(404, "todo not found")
    row = {
        "id": todo_id,
        "title": body.title,
        "completed": body.completed,
        "created_at": STORE[todo_id]["created_at"],
        "priority": body.priority.value,
    }
    STORE[todo_id] = row
    return row


@app.patch("/todos/{todo_id}", response_model=Todo)
def patch_todo(todo_id: str, body: TodoPatch):
    row = STORE.get(todo_id)
    if not row:
        raise HTTPException(404, "todo not found")
    data = body.model_dump(exclude_unset=True)
    if "title" in data:
        row["title"] = data["title"]
    if "completed" in data:
        row["completed"] = data["completed"]
    if data.get("priority") is not None:
        row["priority"] = data["priority"].value
    return row


@app.delete("/todos/{todo_id}", status_code=204)
def delete_todo(todo_id: str):
    if todo_id not in STORE:
        raise HTTPException(404, "todo not found")
    del STORE[todo_id]
    return None
```

Adding an optional request field with a default lets old clients omit it while new servers supply `normal`. An extra response field is safe for clients that ignore unknown properties, and new clients can use a default when an older server does not yet return it. Making `priority` required would reject old requests. Renaming or removing a field, changing its type, or requiring a new path changes an existing client/server expectation and is therefore breaking during a rolling deployment.

```sql
CREATE FUNCTION ch5_check_fields_preserved(old_id integer, candidate_schema jsonb)
RETURNS boolean
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  old_schema jsonb;
BEGIN
  SELECT schema_json INTO old_schema
  FROM ch5_schemas
  WHERE schema_id = old_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'schema % does not exist', old_id;
  END IF;

  RETURN NOT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(old_schema -> 'fields') AS old_field
    WHERE NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(candidate_schema -> 'fields') AS candidate_field
      WHERE candidate_field ->> 'name' = old_field ->> 'name'
    )
  );
END;
$$;

INSERT INTO ch5_schemas (schema_id, schema_json)
SELECT 2, '{"entity":"order","fields":[{"name":"order_id","kind":"string"},{"name":"amount_cents","kind":"integer"},{"name":"currency","kind":"string","default":"USD"}]}'::jsonb
WHERE ch5_check_fields_preserved(
  1,
  '{"entity":"order","fields":[{"name":"order_id","kind":"string"},{"name":"amount_cents","kind":"integer"},{"name":"currency","kind":"string","default":"USD"}]}'::jsonb
);

INSERT INTO ch5_events (schema_id, payload)
SELECT 2, '{"order_id":"ord-200","amount_cents":1299,"currency":"EUR"}'::jsonb
WHERE EXISTS (SELECT 1 FROM ch5_schemas WHERE schema_id = 2);

INSERT INTO ch5_schemas (schema_id, schema_json)
SELECT 3, '{"entity":"order","fields":[{"name":"order_id","kind":"string"},{"name":"currency","kind":"string","default":"USD"}]}'::jsonb
WHERE ch5_check_fields_preserved(
  2,
  '{"entity":"order","fields":[{"name":"order_id","kind":"string"},{"name":"currency","kind":"string","default":"USD"}]}'::jsonb
);

CREATE VIEW ch5_consumer_orders AS
SELECT
  schema_id,
  payload ->> 'order_id' AS order_id,
  (payload ->> 'amount_cents')::integer AS amount_cents,
  COALESCE(payload ->> 'currency', 'USD') AS currency
FROM ch5_events;
```

The additive schema is forward-safe for this old projection because it retains every field name the old consumer reads. Removing `amount_cents` is unsafe because that projection depends on it. This intentionally narrow gate checks names only; it does not validate JSON types, defaults, event payloads, or formal Avro compatibility.

`ch5_normalized_name.sql`:
```sql
DROP TRIGGER IF EXISTS ch5_projects_fill_normalized_name ON ch5_projects;
ALTER TABLE ch5_projects DROP CONSTRAINT IF EXISTS ch5_projects_normalized_name_nn;
DELETE FROM ch5_projects WHERE id = 20001;

CREATE OR REPLACE FUNCTION ch5_normalize_name(p_name text)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
  SELECT lower(btrim(p_name));
$$;

CREATE OR REPLACE FUNCTION ch5_fill_normalized_name()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.normalized_name := ch5_normalize_name(NEW.name);
  RETURN NEW;
END;
$$;

CREATE TRIGGER ch5_projects_fill_normalized_name
BEFORE INSERT OR UPDATE OF name ON ch5_projects
FOR EACH ROW
EXECUTE FUNCTION ch5_fill_normalized_name();

ALTER TABLE ch5_projects
  ADD CONSTRAINT ch5_projects_normalized_name_nn
  CHECK (normalized_name IS NOT NULL) NOT VALID;

CREATE OR REPLACE FUNCTION ch5_backfill_normalized_names(
  p_batch_size integer DEFAULT 2000
)
RETURNS integer
LANGUAGE plpgsql
AS $$
DECLARE
  v_updated_rows integer;
BEGIN
  WITH rows_to_backfill AS (
    SELECT id
    FROM ch5_projects
    WHERE normalized_name IS NULL
    ORDER BY id
    FOR UPDATE SKIP LOCKED
    LIMIT p_batch_size
  )
  UPDATE ch5_projects AS project
  SET normalized_name = ch5_normalize_name(project.name)
  FROM rows_to_backfill
  WHERE project.id = rows_to_backfill.id;

  GET DIAGNOSTICS v_updated_rows = ROW_COUNT;
  RETURN v_updated_rows;
END;
$$;
```

`ch5_finalize.sql`:
```sql
SELECT
  count(*) FILTER (WHERE normalized_name IS NULL) AS null_count,
  count(*) FILTER (
    WHERE normalized_name IS DISTINCT FROM ch5_normalize_name(name)
  ) AS incorrect_count
FROM ch5_projects;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM ch5_projects
    WHERE normalized_name IS NULL
       OR normalized_name IS DISTINCT FROM ch5_normalize_name(name)
  ) THEN
    RAISE EXCEPTION 'cannot finalize: normalized_name backfill is incomplete';
  END IF;
END;
$$;

ALTER TABLE ch5_projects
  VALIDATE CONSTRAINT ch5_projects_normalized_name_nn;
ALTER TABLE ch5_projects
  ALTER COLUMN normalized_name SET NOT NULL;
ALTER TABLE ch5_projects
  DROP CONSTRAINT ch5_projects_normalized_name_nn;

CREATE INDEX CONCURRENTLY ch5_projects_normalized_name_idx
  ON ch5_projects (normalized_name);
ANALYZE ch5_projects;
```

Installing the trigger before backfilling protects rows inserted or renamed while the historical rows are being migrated, so new NULL values cannot race with the backfill. Bounded, independently committed batches hold row locks and generate write-ahead log for a shorter time, reducing contention and making retries less disruptive than one table-wide update.

`activities.py`

```python
import os
import psycopg
from temporalio import activity

def connect():
    return psycopg.connect(os.environ['DATABASE_URL'])

@activity.defn
def request_export(export_id: str) -> None:
    with connect() as db:
        db.execute(
            "INSERT INTO export_jobs (export_id) VALUES (%s) "
            "ON CONFLICT (export_id) DO NOTHING", (export_id,)
        )

def persist_publication(export_id: str, mode: str) -> None:
    with connect() as db:
        job = db.execute(
            "SELECT status FROM export_jobs WHERE export_id=%s FOR UPDATE",
            (export_id,),
        ).fetchone()
        if job is None or job[0] != 'done':
            raise RuntimeError(f'Export {export_id} is not complete')
        db.execute(
            "INSERT INTO publications (export_id, mode) VALUES (%s, %s) "
            "ON CONFLICT (export_id) DO NOTHING", (export_id, mode)
        )

@activity.defn
def publish_export(export_id: str, mode: str) -> None:
    persist_publication(export_id, mode)
    if activity.info().attempt == 1:
        raise RuntimeError("Injected lost acknowledgement after database commit")
```

`workflows.py`

```python
from datetime import datetime, timedelta
from temporalio import workflow
from temporalio.common import RetryPolicy
from activities import publish_export, request_export

@workflow.defn
class MediaExport:
    def __init__(self):
        self.completed_ids = set()

    @workflow.signal
    def export_completed(self, export_id: str):
        self.completed_ids.add(export_id)

    @workflow.run
    async def run(self, request: dict) -> str:
        export_id = request['export_id']
        release_at = datetime.fromisoformat(request['release_at'].replace('Z', '+00:00'))
        activity_options = {
            'start_to_close_timeout': timedelta(seconds=10),
            'retry_policy': RetryPolicy(
                initial_interval=timedelta(seconds=1), maximum_attempts=3
            ),
        }
        await workflow.execute_activity(request_export, export_id, **activity_options)
        await workflow.wait_condition(lambda: export_id in self.completed_ids)
        if workflow.now() < release_at:
            mode = 'scheduled'
            await workflow.sleep(release_at - workflow.now())
        else:
            mode = 'immediate'
        await workflow.execute_activity(
            publish_export, args=[export_id, mode], **activity_options
        )
        return mode
```

The export insert and publication insert are idempotent, while `FOR UPDATE` ensures publication only occurs for a completed job. Signal IDs are accumulated, so duplicate signals are harmless, unrelated IDs do not release the wait, and an early matching signal remains visible.

`verify.py` passed both scheduled and immediate scenarios, including PostgreSQL state, generated CSV artifacts, worker restarts, post-commit Activity retry, and replay. Offline replay passed after release. The deliberate offline-only incompatible change that put `publish_export` before the completion wait failed with Temporal nondeterminism: `Activity machine does not handle this event: HistoryEvent(id: 19, TimerStarted)`. I restored the correct order and replay passed again. `notes.txt` explains persistence across outages, why recorded completed Activities are not re-executed on replay, why idempotency is still required for Activity effects, and why `workflow.now()` is safe while `datetime.now()` is not.
